class Solution {
public:
    int countElements(vector<int>& nums) {
        int cnt=0;
        sort(nums.begin(),nums.end());
        int n=nums.size();
        for(int i=0;i<n;i++)
        {
            if(nums[i]>nums[0] and nums[i]<nums[n-1])
                cnt++;
        }
        return cnt;
    }
};
